#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <cstring>
using namespace std;

struct Edge {
    int to, capacity, flow, rev;
    Edge() {}
    Edge(int t, int c, int f, int r) : to(t), capacity(c), flow(f), rev(r) {}
};

const int MAXN = 121;
vector<Edge> adj[MAXN];
int level[MAXN], start[MAXN], s, t, n;
queue<int> q;

void addEdge(int v, int u, int cap) {
    adj[v].push_back(Edge(u, cap, 0, (int)adj[u].size()));
    adj[u].push_back(Edge(v, 0, 0, (int)adj[v].size() - 1));
}

bool bfs() {
    for (int i = 0; i <= t; ++i) level[i] = -1;
    level[s] = 0;
    q = queue<int>();
    q.push(s);
    while (!q.empty()) {
        int v = q.front(); q.pop();
        for (auto &e : adj[v]) {
            if (level[e.to] < 0 && e.capacity - e.flow > 0) {
                level[e.to] = level[v] + 1;
                q.push(e.to);
            }
        }
    }
    return level[t] >= 0;
}

int pushFlow(int v, int flow) {
    if (v == t) return flow;
    for (int &i = start[v]; i < (int)adj[v].size(); ++i) {
        auto &e = adj[v][i];
        if (level[e.to] == level[v] + 1 && e.capacity - e.flow > 0) {
            int pushed = pushFlow(e.to, min(flow, e.capacity - e.flow));
            if (pushed > 0) {
                e.flow += pushed;
                adj[e.to][e.rev].flow -= pushed;
                return pushed;
            }
        }
    }
    return 0;
}

int main() {
    int n, tbad;
    cin >> n >> tbad;
    char grid[N][N], grid_b[N][N];
    int px, py;
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            cin >> grid[i][j];
            if (grid[i][j] == 'Z') px = i, py = j;
        }
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            cin >> grid_b[i][j];

    s = 0;
    t = 2 * n * n + 1;

    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            int u = i * n + j + 1;
            if (grid[i][j] != '0') addEdge(s, u, grid[i][j] - '0');
            if (grid_b[i][j] != '0') addEdge(u + n * n, t, grid_b[i][j] - '0');
        }

    int totalFlow = 0;
    while (bfs()) {
        for (int i = 0; i <= t; ++i) start[i] = 0;
        int pushed;
        while ((pushed = pushFlow(s, 1e9)) > 0) totalFlow += pushed;
    }
    cout << totalFlow << endl;
    return 0;
}
